import { boot } from 'quasar/wrappers';
import { Icon, addCollection } from '@iconify/vue';
import type { IconifyJSON } from '@iconify/vue';
import { iconBundle } from 'src/icons/mdi-bundle';
import techLogos from 'src/icons/tech-logos.json';
import { safeBoot } from 'src/utils/bootSafety';

/**
 * Iconify Boot File
 *
 * Preloads the MDI icon bundle for offline use and registers the Icon component globally.
 * Icons are registered via addCollection() so they render without CDN calls,
 * which is critical for the PWA offline mode.
 */
export default boot(safeBoot('iconify', ({ app }) => {
  addCollection(iconBundle);
  // Brand logos (postgresql, redis, opensearch, digital-ocean, aws, kong, …)
  // bundled offline so the Infrastructure diagram renders them without CDN calls.
  addCollection(techLogos as unknown as IconifyJSON);
  app.component('Icon', Icon);
}));
